import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    matrix = []
    index = 1

    for i in range(n):
        row = list(map(int, data[index:index + n]))
        matrix.append(row)
        index += n

    if n == 0 or matrix[0][0] == 0:
        return

    paths = []
    current_path = []

    def dfs(row, col):
        if row == n - 1 and col == n - 1:
            paths.append(''.join(current_path))
            return

        if row + 1 < n and matrix[row + 1][col] == 1:
            current_path.append('D')
            dfs(row + 1, col)
            current_path.pop()

        if col + 1 < n and matrix[row][col + 1] == 1:
            current_path.append('R')
            dfs(row, col + 1)
            current_path.pop()

    dfs(0, 0)

    for path in paths:
        print(path)

if __name__ == "__main__":
    main()
